1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type QuoteResult = { premium: number };
25	export type ClaimResult = { payout: number; remainingCap: number };
26	export type Result = QuoteResult | ClaimResult;
27	
28	const PROCESSING_FEE = 5;
29	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
30	const CURSE_SURCHARGE_RATE = 0.5;
31	const HIGH_ENCHANTMENT_THRESHOLD = 5;
32	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
33	const LOYALTY_YEARS_THRESHOLD = 2;
34	const LOYALTY_DISCOUNT_RATE = 0.2;
35	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
36	
37	/**
38	 * What the MHPCO charges to insure a type, before any modifier.
39	 *
40	 * Deliberately NOT the same table as `INSURANCE_VALUES`, and deliberately not
41	 * derived from it — see the note there.
42	 */
43	const BASE_PREMIUMS: Record<string, number> = {
44	  sword: 100,
45	  amulet: 60,
46	  staff: 80,
47	  potion: 40,
48	  rune: 25,
49	  moonstone: 25,
50	};
51	
52	/**
53	 * What the MHPCO considers a type to be WORTH. Only the payout cap reads this.
54	 *
55	 * Every value here is currently exactly 10 × the type's base premium, which
56	 * makes this table look like derivable duplication of `BASE_PREMIUMS`. It is
57	 * not: the two encode different facts that merely agree numerically today. The
58	 * ratio is a coincidence of the MHPCO's price list, not a rule of it.
59	 *
60	 * Collapsing them — `INSURANCE_VALUES[t]` to `BASE_PREMIUMS[t] * 10` — would
61	 * put every premium modifier on the path to the cap, since modifiers apply to
62	 * the base premium. "caps a cursed sword policy at 2000 G based on the
63	 * unmodified insurance value" is the executable guard: the cursed sword's
64	 * premium is modified to 165 G while its cap stays 2 × 1000 = 2000 G. A
65	 * derived table would let the 50 % curse surcharge inflate the cap to 3000 G,
66	 * paying the customer MORE for insuring a cursed item. The separation is what
67	 * keeps premium modifiers out of valuation.
68	 */
69	const INSURANCE_VALUES: Record<string, number> = {
70	  sword: 1000,
71	  amulet: 600,
72	  staff: 800,
73	  potion: 400,
74	  rune: 250,
75	  moonstone: 250,
76	};
77	
78	const DEDUCTIBLE_PER_DAMAGE = 100;
79	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
80	const HALF_REIMBURSEMENT_RATE = 0.5;
81	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
82	
83	const BLOCK_SIZE = 3;
84	const BLOCK_PREMIUM = 60;
85	
86	/** Items that share the same `type`, and so are priced together. */
87	type AlikeItems = Item[];
88	
89	const groupAlikeItems = (items: Item[]): AlikeItems[] => {
90	  const byType = new Map<string, AlikeItems>();
91	  items.forEach((item) => byType.set(item.type, [...(byType.get(item.type) ?? []), item]));
92	  return [...byType.values()];
93	};
94	
95	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
96	
97	const itemBasePremium = (item: Item): number => {
98	  const basePremium = BASE_PREMIUMS[item.type];
99	  if (basePremium === undefined) throw new Error(`The MHPCO does not insure a ${item.type}`);
100	  return basePremium;
101	};
102	
103	const alikeItemsBasePremium = (alikeItems: AlikeItems): number =>
104	  formsBlock(alikeItems)
105	    ? BLOCK_PREMIUM
106	    : alikeItems.reduce((total, item) => total + itemBasePremium(item), 0);
107	
108	const totalBasePremium = (items: Item[]): number =>
109	  groupAlikeItems(items).reduce((total, alikeItems) => total + alikeItemsBasePremium(alikeItems), 0);
110	
111	const isCursed = (item: Item): boolean => item.cursed === true;
112	
113	const isHighlyEnchanted = (item: Item): boolean =>
114	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
115	
116	/**
117	 * An additive rate rule: contributes `rate` × some base premium, but only to
118	 * subjects the rule `applies` to. Every rule is an independent additive term —
119	 * nothing compounds onto a running total — so a discount is simply a negative
120	 * `rate` rather than a subtraction applied at some point in a sequence.
121	 */
122	type RateRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
123	
124	/**
125	 * The combined rate of every rule that applies to `subject`. Callers multiply
126	 * this by the relevant base premium once, which keeps each rule additive.
127	 */
128	const combinedRate = <Subject>(rules: RateRule<Subject>[], subject: Subject): number =>
129	  rules.filter(({ applies }) => applies(subject)).reduce((total, { rate }) => total + rate, 0);
130	
131	const ITEM_SURCHARGES: RateRule<Item>[] = [
132	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
133	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
134	];
135	
136	const itemSurcharge = (item: Item): number =>
137	  itemBasePremium(item) * combinedRate(ITEM_SURCHARGES, item);
138	
139	/**
140	 * Summed across the policy's items, but each term is charged on the item's own
141	 * base premium — so this is item-scoped pricing that merely totals up, unlike
142	 * `policyAdjustments`, which rates the policy base as a whole.
143	 */
144	const itemSurchargesTotal = (items: Item[]): number =>
145	  items.reduce((total, item) => total + itemSurcharge(item), 0);
146	
147	/** Everything a policy-wide rule may look at when deciding whether it applies. */
148	type Policy = { customer: Customer; priorContracts: number };
149	
150	const isLoyalCustomer = ({ customer }: Policy): boolean =>
151	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
152	
153	const isFollowUpContract = ({ priorContracts }: Policy): boolean => priorContracts > 0;
154	
155	/**
156	 * Charged once per quote on the policy's base premium.
157	 *
158	 * The unconditional first-insurance surcharge is deliberately not in this table:
159	 * see `FIRST_INSURANCE_SURCHARGE_RATE` at the quote site.
160	 */
161	const POLICY_ADJUSTMENTS: RateRule<Policy>[] = [
162	  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
163	  { applies: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
164	];
165	
166	const policyAdjustments = (policyBasePremium: number, policy: Policy): number =>
167	  policyBasePremium * combinedRate(POLICY_ADJUSTMENTS, policy);
168	
169	const quotePremium = (items: Item[], policy: Policy): number => {
170	  const policyBasePremium = totalBasePremium(items);
171	  // The first-insurance surcharge has no condition to test: the MHPCO treats
172	  // every item in a quote as newly insured, so it is charged on every quote,
173	  // including a long-standing customer's follow-up contract. That makes it a
174	  // fixed rate on the base — like PROCESSING_FEE is a fixed addend — rather
175	  // than a rule belonging in POLICY_ADJUSTMENTS.
176	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
177	  // Every term is added to the base, never multiplied onto a running total. The
178	  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
179	  // base 100, which Math.ceil turns into a premium that is 1 G too high.
180	  return Math.ceil(
181	    policyBasePremium +
182	      itemSurchargesTotal(items) +
183	      firstInsuranceSurcharge +
184	      policyAdjustments(policyBasePremium, policy) +
185	      PROCESSING_FEE,
186	  );
187	};
188	
189	const isQuote = (step: Step): boolean => step.op === "quote";
190	
191	/**
192	 * A contract is created by each quote, so the number the customer already held
193	 * when `stepIndex` is reached is just the number of quotes before it. Claims are
194	 * not contracts and so do not count.
195	 */
196	const priorContractsAt = (steps: Step[], stepIndex: number): number =>
197	  steps.slice(0, stepIndex).filter(isQuote).length;
198	
199	/**
200	 * The items covered by the policy a claim points at, rejecting a `policy` index
201	 * that names no policy at all.
202	 *
203	 * Named for the rejection rather than the lookup because the throw is the
204	 * interesting half: a claim carries an index into a step list it does not
205	 * control, so "step 3 is a policy" is an assumption to check, not a given.
206	 */
207	const requireInsuredItems = (steps: Step[], policyIndex: number): Item[] => {
208	  const step = steps[policyIndex];
209	  if (step?.op !== "quote") throw new Error(`Step ${policyIndex} did not create a policy`);
210	  return step.items;
211	};
212	
213	/**
214	 * The insured item a damage entry refers to. Matching is by `itemType` only —
215	 * a damage entry names a type, not a specific item, so with several alike items
216	 * on one policy the first match stands in for whichever was damaged.
217	 */
218	const requireDamagedItem = (insured: Item[], damage: Damage): Item => {
219	  const item = insured.find(({ type }) => type === damage.itemType);
220	  if (!item) throw new Error(`Policy does not cover an item of type ${damage.itemType}`);
221	  return item;
222	};
223	
224	/**
225	 * Summed over EVERY item the policy covers, not just a damaged one. A claim on
226	 * one item of a multi-item policy still draws against the whole policy's sum:
227	 * damaging only the amulet of a sword + amulet policy reports a cap of 3200
228	 * (2 × 1600), not 1200 (2 × 600).
229	 *
230	 * Reads the item's `type` and nothing else. An item's `cursed` and `enchantment`
231	 * fields move its premium but never its insured value, so this stays on the
232	 * valuation side of the pricing/valuation split described at `INSURANCE_VALUES`.
233	 */
234	const insuranceSum = (policyItems: Item[]): number =>
235	  policyItems.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
236	
237	/**
238	 * The reimbursable value of a damage before the deductible. Special clauses key
239	 * off the DAMAGED ITEM's own properties, so this takes the insured item rather
240	 * than the damage entry alone.
241	 *
242	 * The spec's dragon-material clause has no branch here on purpose: full
243	 * reimbursement is already the no-clause baseline, and where dragon material
244	 * meets enchantment >= 8 the 50 % rule wins, so a `material === "dragon"`
245	 * branch could only return what these two lines already return.
246	 */
247	const reimbursedAmount = (damage: Damage, insuredItem: Item): number =>
248	  (insuredItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
249	    ? damage.amount * HALF_REIMBURSEMENT_RATE
250	    : damage.amount;
251	
252	/** The deductible is charged per damaged item, not once per incident. */
253	const damagePayout = (damage: Damage, insuredItem: Item): number =>
254	  reimbursedAmount(damage, insuredItem) - DEDUCTIBLE_PER_DAMAGE;
255	
256	const incidentPayout = (damages: Damage[], insured: Item[]): number =>
257	  // Rounded down, in the MHPCO's favor. Applied to the incident total rather
258	  // than to each damage, so a single incident loses at most 1 G to rounding.
259	  Math.floor(
260	    damages.reduce(
261	      (total, damage) => total + damagePayout(damage, requireDamagedItem(insured, damage)),
262	      0,
263	    ),
264	  );
265	
266	/** A policy pays out at most twice the insurance sum of the items it covers. */
267	const payoutCap = (policyItems: Item[]): number =>
268	  insuranceSum(policyItems) * CAP_MULTIPLE_OF_INSURANCE_SUM;
269	
270	/**
271	 * What the policy can still pay after `paidOutSoFar` has been paid against it.
272	 * The cap belongs to the policy, not to a claim, so this subtracts every payout
273	 * the policy has already made — across all earlier claims, not just this one.
274	 */
275	const capRemainingAfter = (policyItems: Item[], paidOutSoFar: number): number =>
276	  payoutCap(policyItems) - paidOutSoFar;
277	
278	/**
279	 * A step is priced against the whole scenario, not just its own fields: a quote
280	 * needs the customer and the steps before it to know about discounts, and a
281	 * claim needs the steps before it to find its policy. Both halves therefore
282	 * take the same two arguments, which is what lets `runScenario` dispatch on
283	 * `op` alone.
284	 */
285	const quoteResult = (scenario: Scenario, stepIndex: number, items: Item[]): QuoteResult => {
286	  const policy = {
287	    customer: scenario.customer,
288	    priorContracts: priorContractsAt(scenario.steps, stepIndex),
289	  };
290	  return { premium: quotePremium(items, policy) };
291	};
292	
293	/**
294	 * Total already paid against each policy, keyed by the policy's step index.
295	 *
296	 * Absent keys mean "nothing paid yet", so this is deliberately partial rather
297	 * than pre-seeded with a 0 per quote: a claim can name any step index, and only
298	 * `requireInsuredItems` gets to decide whether that index is a policy at all.
299	 */
300	type PaidOutByPolicy = Partial<Record<number, number>>;
301	
302	const claimResult = (
303	  scenario: Scenario,
304	  policyIndex: number,
305	  damages: Damage[],
306	  paidOutSoFar: number,
307	): ClaimResult => {
308	  // The same list serves two different scopes: the payout looks up only the
309	  // damaged items within it, while the cap is drawn from all of it.
310	  const policyItems = requireInsuredItems(scenario.steps, policyIndex);
311	  const capRemaining = capRemainingAfter(policyItems, paidOutSoFar);
312	  // The claim can never draw more than the policy has left, so a claim worth
313	  // more than the remaining cap is paid down to exactly that remainder.
314	  const payout = Math.min(incidentPayout(damages, policyItems), capRemaining);
315	  return { payout, remainingCap: capRemaining - payout };
316	};
317	
318	/**
319	 * The result of one step, plus the payouts-so-far that the NEXT step must see.
320	 * A quote returns the tally untouched; a claim returns it with its own payout
321	 * added. Returning the tally rather than mutating a shared one is what lets the
322	 * scenario be a fold over immutable states instead of a map with a side effect.
323	 */
324	const stepResult = (
325	  scenario: Scenario,
326	  step: Step,
327	  stepIndex: number,
328	  paidOut: PaidOutByPolicy,
329	): { result: Result; paidOut: PaidOutByPolicy } => {
330	  if (step.op === "quote") {
331	    return { result: quoteResult(scenario, stepIndex, step.items), paidOut };
332	  }
333	  const paidOutSoFar = paidOut[step.policy] ?? 0;
334	  const result = claimResult(scenario, step.policy, step.incident.damages, paidOutSoFar);
335	  // Read back off the result rather than recomputed: the payout the policy has
336	  // drawn is by definition the payout the customer was told about.
337	  return {
338	    result,
339	    paidOut: { ...paidOut, [step.policy]: paidOutSoFar + result.payout },
340	  };
341	};
342	
343	export const runScenario = (scenario: Scenario): Result[] =>
344	  // A claim's payout depends on what earlier claims against the same policy
345	  // already drew, so the steps are folded with that running total rather than
346	  // mapped independently.
347	  scenario.steps.reduce<{ results: Result[]; paidOut: PaidOutByPolicy }>(
348	    ({ results, paidOut }, step, stepIndex) => {
349	      const stepOutcome = stepResult(scenario, step, stepIndex, paidOut);
350	      return { results: [...results, stepOutcome.result], paidOut: stepOutcome.paidOut };
351	    },
352	    { results: [], paidOut: {} },
353	  ).results;
